'use strict';
let data, original, filter='all', sort='default', query='', scenario='all', stage='all', active=0;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scenarios={'subway-crop':'噪声地铁 · 17.940s 音频裁切','subway-full':'地铁全片 · 40.103s','clean-interview':'清晰访谈 · 68.413s','ocr-heldout':'字幕 OCR · 4 帧留出集','ocr-default':'字幕 OCR · 默认裁切','preparation':'素材准备 · 非推理步骤','bili-acquire':'Bilibili · 页面获取','pricing':'托管服务 · 文档价格','unexecuted':'未执行路线','unassigned':'未标注实验场景'};
const scenarioKey=r=>typeof r.scenario==='string'&&r.scenario?r.scenario:'unassigned';
const scenarioName=k=>scenarios[k]||k;
const labels={measured:'实测',documented:'文档价格',blocked:'受阻'};
const designs=[['workbench','01','证据工作台','分栏对照 · 快速核验','多列信息架构，将原始片段、测量结果与来源放在同一视野。'],['terminal','02','流水线控制台','顺序诊断 · 执行视角','以阶段日志为主线，清楚分开已执行、仅研究和被阻断的步骤。'],['notebook','03','研究手记','结论先行 · 注释阅读','侧栏索引与有编号的证据段落，适合细读方法和转录的局限。'],['timeline','04','时间切片','帧驱动 · 逐段检查','横向时间标尺串起画面和字幕，底部轨道保留基准与获取状态。']];
const badge=s=>`<span class="badge ${s}">${labels[s]||esc(s)}</span>`;
const safeLink=s=>{try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}};
const header=route=>`<header class="top"><a class="brand" href="#/">◈ <span>FRAME<span class="brandlight"> / EVIDENCE LAB</span></span></a><nav aria-label="视图选择">${designs.map(d=>`<a href="#/${d[0]}" ${route===d[0]?'aria-current="page"':''}>${d[1]} ${d[2]}</a>`).join('')}</nav><button class="subtle" data-action="import">导入 JSON</button><input type="file" id="file" accept="application/json,.json" hidden></header>`;
const context=()=>`<div class="context"><span class="eyebrow">PUBLIC SMOKE TEST / ${esc(data.date)}</span><span>${esc(data.title)} · ${data.duration.toFixed(3)}s</span><span class="state">SenseVoice 改善，准确率仍未过关</span></div>`;
const warning=()=>`<div class="warning"><b>结论边界</b><span>tiny 在噪声片段上失败；SenseVoice 参考 CER 降至 60%，仍未达到高准确率。Bilibili 匿名页面部分成功：仅 3 条可见记录、1 条明确评价，不推断总体立场。</span></div>`;
const stats=()=>`<section class="stats" aria-label="关键测量"><div><small>素材长度</small><strong>${data.duration.toFixed(3)}<em>s</em></strong><span>中性公共样本</span></div><div><small>tiny / 热推理</small><strong>0.557<em>s</em></strong><span>17.966s 片段 · beam 5</span></div><div class="bad"><small>参考字幕 CER</small><strong>100<em>%</em></strong><span>错误率，不是准确率</span></div><div><small>已付 API 费用</small><strong>$0</strong><span>基础设施费用未计价</span></div></section>`;
const tools=()=>`<div class="tools"><label>实验场景<select id="scenario"><option value="all">全部场景 · 分组查看</option>${[...new Set(data.rows.map(scenarioKey))].map(k=>`<option value="${esc(k)}" ${scenario===k?'selected':''}>${esc(scenarioName(k))}</option>`).join('')}</select></label><label>流程阶段<select id="stage"><option value="all">全部阶段</option>${[...new Set(data.rows.map(r=>r.stage||'Unspecified'))].map(k=>`<option value="${esc(k)}" ${stage===k?'selected':''}>${esc(k)}</option>`).join('')}</select></label><label>证据类别<select id="filter"><option value="all">全部类别</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select></label><label>排序<select id="sort"><option value="default">流程顺序</option><option value="fast" ${sort==='fast'?'selected':''}>组内耗时 · 从低到高</option><option value="slow" ${sort==='slow'?'selected':''}>组内耗时 · 从高到低</option></select></label><label class="search">查找<input id="query" placeholder="模型、阶段或状态" value="${esc(query)}"></label></div>`;
function rows(){let rs=data.rows.filter(r=>(filter==='all'||r.status===filter)&&(scenario==='all'||scenarioKey(r)===scenario)&&(stage==='all'||(r.stage||'Unspecified')===stage)&&`${r.name} ${r.stage} ${r.quality}`.toLowerCase().includes(query.toLowerCase()));const order=[...new Set(data.rows.map(scenarioKey))];rs.sort((a,b)=>{const group=order.indexOf(scenarioKey(a))-order.indexOf(scenarioKey(b));if(group)return group;if(sort==='default')return 0;return a.seconds==null?b.seconds==null?0:1:b.seconds==null?-1:(sort==='fast'?1:-1)*(a.seconds-b.seconds);});return rs;}
const timing=r=>r.seconds==null?'未测':r.seconds<.001?`${(r.seconds*1000).toFixed(3)} ms`:`${r.seconds.toFixed(3)} s`;
const cost=r=>r.cost==null?'未计价':`${r.currency.startsWith('CNY')?'¥':'$'}${r.cost} ${esc(r.currency.replace(/^(USD|CNY)\s*/,'').trim())}${r.status==='measured'?' API':''}`;
const table=()=>{const selected=rows();const groups=[...new Set(selected.map(scenarioKey))];return `${groups.length>1||groups.includes('unassigned')?`<div class="comparisonnotice" role="note"><b>不同场景，不能直接排名</b><span>时长、素材、任务与参考不同；CER / 耗时仅在可比实验内解读。排序只作用于各场景内部。未标注场景的导入数据不可默认互相可比。</span></div>`:''}<div class="tablewrap"><table><thead><tr><th>路线 / 阶段</th><th>依据</th><th>耗时</th><th>质量 / 范围</th><th>费用口径</th></tr></thead><tbody>${groups.map(k=>`<tr class="scenarioheading"><th colspan="5">${esc(scenarioName(k))}${k==='subway-crop'?'<small> 同源裁切：音频 17.940s / 重编码容器 17.966s；预处理与推理分开计时</small>':''}</th></tr>${selected.filter(r=>scenarioKey(r)===k).map(r=>`<tr><td><button class="rowlink" data-row="${esc(r.id)}">${esc(r.name)}</button><small>${esc(r.stage)} ${esc(r.run||'')}</small></td><td>${badge(r.status)}</td><td class="number">${timing(r)}</td><td>${esc(r.quality)}${r.cer!=null?`<small class="red">CER ${(r.cer*100).toFixed(2)}%</small>`:''}</td><td>${cost(r)}</td></tr>`).join('')}`).join('')||'<tr><td colspan="5">没有匹配记录。请调整场景、类别、阶段或搜索词。</td></tr>'}</tbody></table></div>`;};
const captions=()=>`<div class="captions">${data.captions.map(c=>`<div class="cue"><small>${esc(c.time.replaceAll(',','.'))}</small><p>${esc(c.text)}</p></div>`).join('')}</div><p class="fine">已发布字幕，未经独立听校。第 5 条有省略号，不能作为完整逐字参考。</p>`;
const frames=(large=false)=>`<div class="frames ${large?'large':''}">${data.frames.map((f,i)=>`<button data-frame="${i}" class="frame ${active===i?'selected':''}"><img src="${esc(f.src)}" alt="北京地铁公共样本，约 ${f.time} 秒画面"><span>≈ 00:${String(f.time).padStart(2,'0')} <i>FRAME ${i+1}</i></span></button>`).join('')}</div>`;
const comments=()=>`<section class="casecard"><div class="sectionhead"><h3>真实案例 / Bilibili 匿名可见部分</h3><span class="badge measured">部分成功</span></div><a class="casetitle" href="${safeLink(data.commentSummary.source)}" target="_blank" rel="noreferrer">${esc(data.commentSummary.title)}</a><p class="fine">${esc(data.commentSummary.bvid)} · 页面显示 ${esc(data.commentSummary.displayDuration)} · 观察于 2026-10-04 22:47 +08:00</p><div class="casecounts"><div><strong>3</strong><span>可见记录</span></div><div><strong>2 + 1</strong><span>根评论 + 表情回复</span></div><div><strong>1</strong><span>明确评价</span></div><div><strong>49</strong><span>页面显示总数</span></div></div><p>${esc(data.commentSummary.positiveParaphrase)}<small>（简短转述，未展示原评论语料或用户档案）</small></p><ul>${data.commentSummary.excluded.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="warning"><b>不报告总体占比</b><span>${esc(data.commentSummary.limit)} 评论只能证明作者的体验表达，不能验证视频技术论点。</span></div><p class="fine">${esc(data.commentSummary.method)} 直接 HTTP/API 路线曾返回 412；浏览器部分成功不代表完整获取成功。播放器显示登录 / 30 秒试看，评论区提示登录后查看 49 条。</p></section>`;
const visualEvidence=()=>`<section class="visualqa"><div class="sectionhead"><h2>画面证据 / 5 个可核验问题</h2><span>助手看帧示范 · 非盲测</span></div><p class="fine">声音不能证明画面颜色、动作或屏幕文字。以下判断来自现有 v1 抽帧，时间近似；不报告准确率百分比。</p><div class="visualquestions">${data.visualEvidence.items.map((v,i)=>`<button data-visual="${i}"><span class="badge ${v.status==='unanswerable'?'blocked':'measured'}">${v.status==='unanswerable'?'不可回答':v.status==='supported_with_limit'?'有条件支持':'画面支持'}</span><strong>${esc(v.question)}</strong><small>≈ ${v.approximate_seconds.join(' / ')}s · 查看依据</small></button>`).join('')}</div></section>`;
const methodology=()=>`<section class="method"><h3>测量口径 / Method</h3><p>4 CPU 线程 · INT8 · temperature 0 · VAD 关闭 · word timestamps 开启。相同裁切素材、参考和 tiny 权重；首次与热运行各一次，无法可靠估计方差。</p><p>CER =（替换 + 删除 + 插入）/ 参考字符数。当前参考来自已发布字幕，未独立听校；繁简差异计作错误。40.103s 全片没有完整参考，不计算总体 CER。</p><p>字幕 OCR 另有同一访谈视频的 4 帧留出评估（99 字、助手目读参考）：基线 CER 75.76%，预处理后 5.05%；平均 0.301s 与 0.190s。不是语音准确率，也不证明跨视频泛化。详细记录列出裁切和分辨率等混合变化。</p><p>SenseVoice INT8 独立实测：地铁参考 65 字、39 次编辑，CER 60%；热推理 0.592s，模型载入 1.071s，权重约 239 MB。空白/重复门通过，不代表准确率认证。模型采用 <a href="https://github.com/modelscope/FunASR/blob/main/MODEL_LICENSE" target="_blank" rel="noreferrer">FunASR MODEL_LICENSE 1.1 自定义许可</a>，不是 Apache 2；权重不随源码分发。清晰访谈缺乏完整独立参考，不评分。</p><p>同地铁片段的两项预设降噪没有改善：SenseVoice 未处理参考 CER 60%；语音带通 86.15%，轻度 afftdn 81.54%。这些是单片探索结果，不能推断降噪普遍有效或无效；表格耗时为推理，预处理开销在证据抽屉单独列出。</p><p>工作流 v2 的新运行支持精确源 PTS，并通过 9 项便携测试；本页面现有基准与帧图仍来自 v1，不能追溯升级为精确时间。</p><p>帧时间为 FFmpeg 周期采样的近似位置，尚未验证精确 PTS；画面、声音和评论分别保留来源，不能互相代替证据。</p><p>API 账单为 $0。云 CPU、存储、传输费用未计价。文档价格截至 2026-10-04，未实际调用；不同币种和计价单位不作直接排名。</p><p class="fine">公共素材：<a href="${safeLink(data.source)}" target="_blank" rel="noreferrer">${esc(data.license)}</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA 4.0</a>。所示帧为原视频抽取，保留同许可。</p></section>`;
const footer=()=>`<footer><span>FRAME / EVIDENCE LAB</span><span>只读快照 · 本地导入不上传 · 无后端与外部 API 调用</span><button data-action="reset">恢复内置数据</button><a href="data.json" download="video-evidence.json">下载示例 JSON</a></footer>`;
function hub(){return `<main id="main" class="hub"><div class="hubtitle"><span class="eyebrow">FOUR WAYS TO INSPECT THE SAME EVIDENCE</span><h1>视频证据，<br><span>换个视角看清。</span></h1><p>同一素材与测量结果。选择适合当前任务的工作界面。</p></div><div class="designs">${designs.map((d,i)=>`<a class="design design${i}" href="#/${d[0]}"><div class="mini mini${i}">${Array.from({length:7},(_,j)=>`<i class="m${j}"></i>`).join('')}</div><div class="designtext"><span class="index">${d[1]}</span><div><h2>${d[2]}</h2><b>${d[3]}</b><p>${d[4]}</p></div><span class="open">打开</span></div></a>`).join('')}</div>${warning()}<div class="hubmeta"><span>40.103s 公共样本</span><span>6 条字幕</span><span>4 张实帧</span><span>3 条匿名可见记录</span></div></main>`;}
function workbench(){return `<main id="main" class="workbench">${context()}${stats()}<div class="workgrid"><aside class="panel sourcepanel"><div class="sectionhead"><h2>01 / 素材证据</h2><a href="${safeLink(data.source)}" target="_blank" rel="noreferrer">来源</a></div>${frames()}<h3>原始字幕</h3>${captions()}</aside><section class="panel compare"><div class="sectionhead"><h2>02 / 路线比较</h2><span>点击记录核验证据</span></div>${warning()}${tools()}<div id="results">${table()}</div>${comments()}</section></div>${methodology()}</main>`;}
function terminal(){return `<main id="main" class="terminal"><div class="terminalbar"><span>● video-evidence / run-20261004</span><span>READ ONLY · CPU / 4T / INT8</span></div><div class="terminalgrid"><aside class="rail"><h1>PIPELINE<br>INSPECTOR</h1><p>执行记录</p>${['ACQUIRE','DECODE','FRAMES','CAPTIONS','ASR','OCR','COMMENTS'].map((s,i)=>`<a href="#stage-${s}"><span>0${i+1}</span>${s}</a>`).join('')}<div class="railnote">高准确率门槛<br><b>NOT PASSED</b></div></aside><div class="terminalmain">${context()}${warning()}<div class="logstages">${[['ACQUIRE','公共样本可用；Bilibili 匿名页面部分成功','measured'],['DECODE','音频提取 0.169s / 16 kHz PCM','measured'],['FRAMES','4 张均匀帧 / 1.109s','measured'],['CAPTIONS','6 条已发布字幕 / 0.260ms 解析','measured'],['ASR','tiny CER 100% / SenseVoice CER 60%；仍需核验','measured'],['OCR','14 次执行 / 平均 0.262s / 质量较低','measured'],['COMMENTS','3 条可见记录 / 1 条明确评价；总体占比不报告','measured']].map((s,i)=>`<section id="stage-${s[0]}" class="logrow"><span>0${i+1}</span><b>${s[0]}</b><p>${s[1]}</p>${badge(s[2])}</section>`).join('')}</div><div class="sectionhead"><h2>BENCHMARK RECORDS</h2><span>NULL ≠ ZERO</span></div>${tools()}<div id="results">${table()}</div>${frames()}${comments()}<details><summary>展开字幕证据和实验口径</summary>${captions()}${methodology()}</details></div></div></main>`;}
function notebook(){return `<main id="main" class="notebook"><aside class="bookindex"><span class="eyebrow">FIELD NOTES / 001</span><h1>视频分析<br>实验手记</h1><p>2026.10.04</p><nav><a href="#note-conclusion">01 / 结论与边界</a><a href="#note-source">02 / 原始证据</a><a href="#note-bench">03 / 对照测量</a><a href="#note-comments">04 / 部分评论</a><a href="#note-method">05 / 测量口径</a></nav><span class="seal">要有证据<br>才下结论</span></aside><article class="paper"><section id="note-conclusion"><span class="eyebrow">01 / FINDING</span><h2>流程可运行。<br>准确率仍未过关。</h2><p class="lead">噪声与混响下，tiny 返回重复或空白。独立 SenseVoice 路线将参考 CER 从 100% 降到 60%，但仍不能放心逐字引用。运行速度与质量门通过，都不能代替准确率。</p>${stats()}${warning()}</section><section id="note-source"><div class="sectionhead"><h2>02 / 原始证据</h2><a href="${safeLink(data.source)}" target="_blank" rel="noreferrer">公共素材来源</a></div>${frames()}<div class="transcriptpaper">${captions()}</div></section><section id="note-bench"><h2>03 / 对照测量</h2><p>实测、文档价格和阻断记录分开标注。选择一条记录可查看完整口径。</p>${tools()}<div id="results">${table()}</div></section><section id="note-comments"><h2>04 / 部分可见的评论证据</h2>${comments()}</section><section id="note-method">${methodology()}</section></article></main>`;}
function timeline(){const f=data.frames[active];return `<main id="main" class="timeline">${context()}<div class="screenlayout"><section class="screen"><img id="hero-frame" src="${esc(f.src)}" alt="北京地铁公共视频约 ${f.time} 秒的抽取画面"><div class="screenlabel"><span>PUBLIC SOURCE / FRAME ${active+1}</span><b>≈ ${f.time}.000s</b></div><div class="screenbottom"><span>北京地铁 · 公共素材帧</span><small>近似采样时间 · 不代表精确事件边界</small></div></section><aside class="timelinecaptions"><div class="sectionhead"><h2>字幕轨</h2><span>6 CUES</span></div>${captions()}</aside></div><section class="filmstrip"><div class="ruler"><span>00:00</span><span>00:10</span><span>00:20</span><span>00:30</span><span>00:40</span></div>${frames(true)}</section>${visualEvidence()}<div class="lowertracks"><section><div class="sectionhead"><h2>测量轨 / Benchmark</h2><span>速度与质量一起读</span></div>${warning()}${tools()}<div id="results">${table()}</div></section><aside>${stats()}${comments()}</aside></div><details><summary>实验口径与来源许可</summary>${methodology()}</details></main>`;}
function render(){let route=location.hash.split('/')[1]||'';document.body.className=route||'home';$('#app').innerHTML=header(route)+({workbench,terminal,notebook,timeline}[route]||hub)()+footer();bind();}
function detail(r){$('#detail').innerHTML=`<span class="eyebrow">EVIDENCE RECORD / ${esc(r.stage)}</span><h2>${esc(r.name)}</h2>${badge(r.status)}<dl><dt>实验场景</dt><dd>${esc(scenarioName(scenarioKey(r)))}</dd><dt>测量耗时</dt><dd>${timing(r)}</dd><dt>质量</dt><dd>${esc(r.quality)}</dd><dt>费用</dt><dd>${cost(r)}</dd><dt>参考 CER</dt><dd>${r.cer==null?'未测 / 不适用':`${(r.cer*100).toFixed(2)}%（错误率）`}</dd></dl><h3>口径与局限</h3><p>${esc(r.note)}</p><a class="primary" href="${safeLink(r.source)}" target="_blank" rel="noreferrer">打开来源文档</a>`;$('#evidence').showModal();}
function bind(){for(const b of document.querySelectorAll('[data-visual]'))b.onclick=()=>{const v=data.visualEvidence.items[Number(b.dataset.visual)];$('#detail').innerHTML=`<span class="eyebrow">VISUAL EVIDENCE / ${esc(v.basis)}</span><h2>${esc(v.question)}</h2><p>${esc(v.answer)}</p><div class="visualdetailframes">${v.approximate_seconds.map(t=>{const f=data.frames.find(f=>f.time===t);return `<figure><img src="${esc(f.src)}" alt="约 ${t} 秒证据帧"><figcaption>≈ ${t}s · v1 近似位置</figcaption></figure>`}).join('')}</div><p class="fine">${esc(data.visualEvidence.evaluationNote)} ${esc(data.visualEvidence.timingNote)}</p>`;$('#evidence').showModal();};for(const a of document.querySelectorAll('a[href^="#stage-"],a[href^="#note-"]'))a.onclick=e=>{e.preventDefault();document.getElementById(a.getAttribute('href').slice(1))?.scrollIntoView({behavior:'smooth'});};for(const b of document.querySelectorAll('[data-row]'))b.onclick=()=>detail(data.rows.find(r=>r.id===b.dataset.row));for(const b of document.querySelectorAll('[data-frame]'))b.onclick=()=>{active=Number(b.dataset.frame);if(location.hash==='#/timeline'){render();}else{const f=data.frames[active];$('#detail').innerHTML=`<span class="eyebrow">FRAME EVIDENCE / ≈ ${f.time}s</span><h2>北京地铁 · 样本画面</h2><img class="detailimage" src="${esc(f.src)}" alt="约 ${f.time} 秒的抽取画面"><p>FFmpeg 周期采样，未校验精确 PTS。仅此帧不能证明前后发生的短暂动作。</p><p>${esc(data.license)}</p><a href="${safeLink(data.source)}" target="_blank" rel="noreferrer">查看原始素材</a>`;$('#evidence').showModal();}};if($('#scenario'))$('#scenario').onchange=e=>{scenario=e.target.value;updateResults();};if($('#stage'))$('#stage').onchange=e=>{stage=e.target.value;updateResults();};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;updateResults();};if($('#sort'))$('#sort').onchange=e=>{sort=e.target.value;updateResults();};if($('#query'))$('#query').oninput=e=>{query=e.target.value;updateResults();};for(const b of document.querySelectorAll('[data-action="import"]'))b.onclick=()=>$('#file').click();$('#file').onchange=importJSON;for(const b of document.querySelectorAll('[data-action="reset"]'))b.onclick=()=>{data=structuredClone(original);filter='all';sort='default';query='';scenario='all';stage='all';active=0;render();toast('已恢复内置实测快照');};}
function updateResults(){$('#results').innerHTML=table();bind();}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function importJSON(e){const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error('文件需小于 1 MB');const j=JSON.parse(await f.text());if(j.schemaVersion!==1||!Array.isArray(j.rows)||j.rows.length>200)throw Error('需要 schemaVersion: 1 和最多 200 条 rows');if(!j.rows.every(r=>typeof r.id==='string'&&typeof r.name==='string'&&['measured','documented','blocked'].includes(r.status)&&(r.seconds===null||Number.isFinite(r.seconds))&&(r.cer===null||(Number.isFinite(r.cer)&&r.cer>=0))&&(r.cost===null||Number.isFinite(r.cost))&&typeof r.currency==='string'&&(r.scenario===undefined||typeof r.scenario==='string')))throw Error('记录字段无效。请以下载的示例 JSON 为模板。');data={...original,rows:j.rows};if(scenario!=='all'&&!j.rows.some(r=>scenarioKey(r)===scenario))scenario='all';if(stage!=='all'&&!j.rows.some(r=>(r.stage||'Unspecified')===stage))stage='all';active=0;render();toast(`本地预览 ${j.rows.length} 条导入记录。样本画面与字幕保持内置来源；刷新后清除。`);}catch(err){toast('无法导入：'+err.message);}finally{e.target.value='';}}
$('#evidence .close').onclick=()=>$('#evidence').close();$('#evidence').onclick=e=>{if(e.target===$('#evidence'))$('#evidence').close();};window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/')||location.hash==='')render();});fetch('data.json').then(r=>{if(!r.ok)throw Error('数据读取失败');return r.json();}).then(j=>{data=j;original=structuredClone(j);render();}).catch(()=>{$('#app').innerHTML='<main><h1>数据未能载入</h1><p>请刷新页面重试。本页需要同目录的 data.json。</p></main>';});
